begin;
do $$
declare admin_id uuid; counselor uuid:=gen_random_uuid(); student uuid:=gen_random_uuid(); other_student uuid:=gen_random_uuid(); unverified uuid:=gen_random_uuid(); blocked boolean; payload jsonb; receipt text;
begin
 select id into admin_id from public.profiles where role='admin' limit 1;
 if admin_id is null then raise exception 'Admin fixture required';end if;
 insert into auth.users(id,email,email_confirmed_at) select id,id::text||'@test.invalid',now() from unnest(array[counselor,student,other_student])id;
 insert into auth.users(id,email)values(unverified,unverified::text||'@test.invalid');
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 update public.profiles set role='counselor' where id=counselor;
 insert into public.counselor_profiles(user_id,approval_status)values(counselor,'approved');
 payload:=jsonb_build_object('full_name','دانش آموز آزمایشی','phone','09121234567','telegram_id','student_1','grade',11,'study_field','humanities','province','تهران','city','تهران','additional_notes','یادداشت آزمایشی');
 perform set_config('request.jwt.claim.sub',unverified::text,true);
 execute 'set local role authenticated';
 blocked:=false;begin perform public.save_student_account_details(payload);exception when others then blocked:=true;end;if not blocked then raise exception 'Unverified email saved account';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',student::text,true);
 execute 'set local role authenticated';
 perform public.save_student_account_details(payload);
 if not exists(select 1 from public.student_account_details where student_id=student) then raise exception 'Account not saved';end if;
 if (select registration_status from public.profiles where id=student)<>'incomplete' then raise exception 'Account self activated';end if;
 if exists(select 1 from public.student_registrations where student_id=student) then raise exception 'Basic account fabricated enrollment';end if;
 blocked:=false;begin perform public.admin_activate_student_without_receipt(student,counselor);exception when others then blocked:=true;end;if not blocked then raise exception 'Student manually self activated';end if;
 blocked:=false;begin update public.profiles set registration_status='active' where id=student;exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Student can write activation column';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',counselor::text,true);
 execute 'set local role authenticated';
 if exists(select 1 from public.student_account_details where student_id=student) then raise exception 'Counselor read private normal account';end if;
 blocked:=false;begin perform public.admin_activate_student_without_receipt(student,counselor);exception when others then blocked:=true;end;if not blocked then raise exception 'Counselor manually activated student';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 execute 'set local role authenticated';
 blocked:=false;begin perform public.admin_activate_student(student,counselor,null);exception when others then blocked:=true;end;if not blocked then raise exception 'Normal paid approval bypassed receipt';end if;
 blocked:=false;begin perform public.admin_activate_student_without_receipt(other_student,counselor);exception when others then blocked:=true;end;if not blocked then raise exception 'Incomplete account manually activated';end if;
 perform public.admin_activate_student_without_receipt(student,counselor);
 if not exists(select 1 from public.profiles where id=student and registration_status='active') or not exists(select 1 from public.counselor_students where student_id=student and counselor_id=counselor) then raise exception 'Manual activation not atomic with assignment';end if;
 if not exists(select 1 from public.student_manual_activations where student_id=student and activated_by=admin_id) then raise exception 'Manual approval not audited';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',student::text,true);
 execute 'set local role authenticated';
 perform public.save_student_account_details(payload||'{"city":"شیراز"}'::jsonb);
 if (select registration_status from public.profiles where id=student)<>'active' then raise exception 'Account save deactivated active services';end if;
 if exists(select 1 from public.student_manual_activations) then raise exception 'Student read admin-only audit';end if;
 execute 'reset role';
 -- A separate confirmed student uses the normal paid course path.
 receipt:=other_student::text||'/fixture.png';
 insert into storage.objects(bucket_id,name,metadata)values('registration-receipts',receipt,'{"mimetype":"image/png","size":100}');
 perform set_config('request.jwt.claim.sub',other_student::text,true);
 execute 'set local role authenticated';
 payload:=payload||jsonb_build_object('receipt_path',receipt,'receipt_name','fixture.png','course_type','with_support','course_duration_months',6);
 blocked:=false;begin perform public.submit_student_registration(payload-'receipt_path');exception when others then blocked:=true;end;if not blocked then raise exception 'Paid request accepted without receipt';end if;
 blocked:=false;begin perform public.submit_student_registration(payload||'{"course_duration_months":4}'::jsonb);exception when others then blocked:=true;end;if not blocked then raise exception 'Invalid course duration accepted';end if;
 blocked:=false;begin perform public.submit_student_registration(payload||'{"course_type":null}'::jsonb);exception when others then blocked:=true;end;if not blocked then raise exception 'Half selection accepted';end if;
 perform public.submit_student_registration(payload);
 if not exists(select 1 from public.student_registrations where student_id=other_student and course_type='with_support' and course_duration_months=6 and additional_notes='یادداشت آزمایشی') then raise exception 'Course details not persisted';end if;
 if (select registration_status from public.profiles where id=other_student)<>'pending' then raise exception 'Paid request self activated';end if;
 if exists(select 1 from public.student_account_details where student_id=student) then raise exception 'Student read other account';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 execute 'set local role authenticated';
 blocked:=false;begin perform public.admin_activate_student(other_student,counselor,'stale');exception when others then blocked:=true;end;if not blocked then raise exception 'Stale receipt accepted';end if;
 perform public.admin_activate_student(other_student,counselor,receipt);
 execute 'reset role';
end;$$;
select 'Course, email, receipt, private-account and manual-activation tests passed (rolled back)' as result;
rollback;
